// tb.v: random-stimulus testbench for UartTx_16_1, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg tx_valid = 1'b0;
    reg [7:0] tx_data = 8'd0;
    wire tx_ready;
    wire txd;
    reg [8:0] stim [0:239];
    integer i;

    UartTx_16_1 dut (
        .clk(clk),
        .rst(rst),
        .tx_valid(tx_valid),
        .tx_data(tx_data),
        .tx_ready(tx_ready),
        .txd(txd)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {tx_valid, tx_data} = stim[i];
            #1;
            $display("D %0d %h %h", i, tx_ready, txd);
            cycle_clk;
        end
        $finish;
    end
endmodule
